files.content:
/* Palette: #1e1e2f (bg), #2a2a40 (card), #f0f0f5 (text), #6c63ff (accent), #ff6584 (danger) */
* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

[hidden] {
  display: none !important;
}

body {
  font-family: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
  font-size: 16px;
  background: #1e1e2f;
  color: #f0f0f5;
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 24px 16px;
}

.card {
  background: #2a2a40;
  border-radius: 16px;
  padding: 28px 24px;
  width: 100%;
  max-width: 720px;
  box-shadow: 0 8px 32px rgba(0, 0, 0, 0.4);
}

header {
  margin-bottom: 24px;
}

h1 {
  font-size: 1.75rem;
  font-weight: 700;
  letter-spacing: -0.02em;
}

.subtitle {
  color: #a0a0b8;
  font-size: 0.95rem;
  margin-top: 4px;
}

.line-item {
  display: grid;
  grid-template-columns: 2fr 0.7fr 1fr 1fr auto;
  gap: 8px;
  align-items: center;
  padding: 8px 0;
  border-bottom: 1px solid #3a3a55;
}

.line-item-header {
  font-size: 0.8rem;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  color: #a0a0b8;
  font-weight: 600;
  border-bottom: 2px solid #3a3a55;
  padding-bottom: 8px;
}

.line-item input {
  width: 100%;
  padding: 10px 12px;
  border-radius: 8px;
  border: 1px solid #3a3a55;
  background: #1e1e2f;
  color: #f0f0f5;
  font-size: 1rem;
  font-family: inherit;
  transition: border-color 0.15s, box-shadow 0.15s;
}

.line-item input:focus {
  outline: none;
  border-color: #6c63ff;
  box-shadow: 0 0 0 3px rgba(108, 99, 255, 0.3);
}

.line-item input:hover {
  border-color: #6c63ff;
}

.line-total {
  font-variant-numeric: tabular-nums;
  text-align: right;
  font-weight: 600;
  padding-right: 4px;
}

.btn {
  font-family: inherit;
  font-size: 1rem;
  font-weight: 600;
  border: none;
  border-radius: 8px;
  cursor: pointer;
  padding: 10px 18px;
  transition: background 0.15s, transform 0.1s, box-shadow 0.15s;
  min-height: 44px;
}

.btn:focus-visible {
  outline: 3px solid #6c63ff;
  outline-offset: 2px;
}

.btn-add {
  background: #6c63ff;
  color: #fff;
  width: 100%;
  margin: 16px 0 24px;
}

.btn-add:hover {
  background: #5a52e0;
}

.btn-add:active {
  transform: scale(0.98);
}

.btn-remove {
  background: transparent;
  color: #ff6584;
  font-size: 1.2rem;
  padding: 6px 10px;
  line-height: 1;
  min-height: 44px;
  min-width: 44px;
  border-radius: 8px;
}

.btn-remove:hover {
  background: rgba(255, 101, 132, 0.15);
}

.btn-remove:active {
  transform: scale(0.92);
}

.summary {
  border-top: 2px solid #3a3a55;
  padding-top: 16px;
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.summary-row {
  display: flex;
  justify-content: space-between;
  align-items: center;
  font-size: 1rem;
}

.summary-row label {
  color: #a0a0b8;
}

.summary-row input {
  width: 100px;
  padding: 8px 12px;
  border-radius: 8px;
  border: 1px solid #3a3a55;
  background: #1e1e2f;
  color: #f0f0f5;
  font-size: 1rem;
  font-family: inherit;
  text-align: right;
  transition: border-color 0.15s, box-shadow 0.15s;
}

.summary-row input:focus {
  outline: none;
  border-color: #6c63ff;
  box-shadow: 0 0 0 3px rgba(108, 99, 255, 0.3);
}

.summary-row input:hover {
  border-color: #6c63ff;
}

.total-row {
  font-size: 1.25rem;
  font-weight: 700;
  border-top: 1px solid #3a3a55;
  padding-top: 12px;
  margin-top: 4px;
}

.total-row span:last-child {
  color: #6c63ff;
}

.empty-message {
  text-align: center;
  color: #a0a0b8;
  font-size: 0.95rem;
  padding: 24px 0 8px;
}

@media (max-width: 520px) {
  .card {
    padding: 20px 16px;
  }
  .line-item {
    grid-template-columns: 1fr 1fr;
    gap: 6px;
    padding: 10px 0;
  }
  .line-item-header {
    display: none;
  }
  .line-item input {
    padding: 8px 10px;
  }
  .line-item .line-total {
    text-align: left;
    padding: 4px 0;
  }
  .line-item .btn-remove {
    justify-self: end;
  }
  .summary-row input {
    width: 80px;
  }
}

(function () {
  'use strict';

  const itemsContainer = document.getElementById('items-container');
  const addBtn = document.getElementById('add-item');
  const subtotalEl = document.getElementById('subtotal');
  const taxAmountEl = document.getElementById('tax-amount');
  const grandTotalEl = document.getElementById('grand-total');
  const taxRateInput = document.getElementById('tax-rate');
  const emptyMessage = document.getElementById('empty-message');

  let itemCount = 0;

  function formatCurrency(value) {
    return '$' + value.toFixed(2);
  }

  function calculateTotals() {
    let subtotal = 0;
    const rows = itemsContainer.querySelectorAll('.line-item');
    rows.forEach(function (row) {
      const qty = parseFloat(row.querySelector('.qty').value) || 0;
      const price = parseFloat(row.querySelector('.price').value) || 0;
      const lineTotal = qty * price;
      row.querySelector('.line-total').textContent = formatCurrency(lineTotal);
      subtotal += lineTotal;
    });

    const taxRate = parseFloat(taxRateInput.value) || 0;
    const tax = subtotal * (taxRate / 100);
    const grandTotal = subtotal + tax;

    subtotalEl.textContent = formatCurrency(subtotal);
    taxAmountEl.textContent = formatCurrency(tax);
    grandTotalEl.textContent = formatCurrency(grandTotal);

    emptyMessage.hidden = rows.length > 0;
  }

  function createRow() {
    itemCount++;
    const id = 'item-' + itemCount;
    const row = document.createElement('div');
    row.className = 'line-item';

    const descInput = document.createElement('input');
    descInput.type = 'text';
    descInput.className = 'desc';
    descInput.placeholder = 'Description';
    descInput.setAttribute('aria-label', 'Line item description');

    const qtyInput = document.createElement('input');
    qtyInput.type = 'number';
    qtyInput.min = '0';
    qtyInput.step = '1';
    qtyInput.value = '1';
    qtyInput.className = 'qty';
    qtyInput.setAttribute('aria-label', 'Quantity');

    const priceInput = document.createElement('input');
    priceInput.type = 'number';
    priceInput.min = '0';
    priceInput.step = '0.01';
    priceInput.value = '0.00';
    priceInput.className = 'price';
    priceInput.setAttribute('aria-label', 'Unit price');

    const totalSpan = document.createElement('span');
    totalSpan.className = 'line-total';
    totalSpan.textContent = '$0.00';
    totalSpan.setAttribute('aria-label', 'Line total');

    const removeBtn = document.createElement('button');
    removeBtn.type = 'button';
    removeBtn.className = 'btn btn-remove';
    removeBtn.textContent = '×';
    removeBtn.setAttribute('aria-label', 'Remove line item');
    removeBtn.addEventListener('click', function () {
      row.remove();
      calculateTotals();
    });

    row.appendChild(descInput);
    row.appendChild(qtyInput);
    row.appendChild(priceInput);
    row.appendChild(totalSpan);
    row.appendChild(removeBtn);

    [descInput, qtyInput, priceInput].forEach(function (input) {
      input.addEventListener('input', calculateTotals);
    });

    itemsContainer.appendChild(row);
    calculateTotals();
    descInput.focus();
  }

  addBtn.addEventListener('click', createRow);
  taxRateInput.addEventListener('input', calculateTotals);

  // Initialize with one row
  createRow();
})();
